// GetByEmail retrieves a paginated page of Customer entities by their Email index.
func (r *customerRepository) GetByEmail(ctx context.Context, tx fdblayer.ReadTx, Email string, opts fdblayer.PaginationOptions) (*fdblayer.PaginatedResult[*Customer], error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	tr := tx.ReadTransaction()
	dir := tx.Dir()

	cursorBegin, err := opts.EffectiveBegin()
	if err != nil {
		return nil, err
	}
	result := &fdblayer.PaginatedResult[*Customer]{
		Items: make([]*Customer, 0),
	}
	baseTpl := tuple.Tuple{CustomerTypeID, fdblayer.IndexNamespace, 1, Email}
	indexKeyPrefix := dir.Pack(baseTpl)
	indexRange, err := fdb.PrefixRange(indexKeyPrefix)
	if err != nil {
		return nil, err
	}
	rangeBegin := indexRange.Begin
	rangeEnd := indexRange.End
	if len(cursorBegin) > 0 {
		cursorTpl := make(tuple.Tuple, len(baseTpl)+len(cursorBegin))
		copy(cursorTpl, baseTpl)
		for j, el := range cursorBegin {
			cursorTpl[len(baseTpl)+j] = fdblayer.NormalizeTupleElement(el)
		}
		cursorKey := dir.Pack(cursorTpl)
		if opts.Reverse {
			cursorRange, err := fdb.PrefixRange(cursorKey)
			if err != nil {
				return nil, err
			}
			if string(cursorRange.End.FDBKey()) < string(rangeEnd.FDBKey()) {
				rangeEnd = cursorRange.End
			}
		} else if string(cursorKey) > string(rangeBegin.FDBKey()) {
			rangeBegin = cursorKey
		}
	}
	if string(rangeBegin.FDBKey()) >= string(rangeEnd.FDBKey()) {
		return result, nil
	}
	rangeOpts := fdb.RangeOptions{Reverse: opts.Reverse}
	if opts.Limit > 0 {
		rangeOpts.Limit = opts.Limit + 1
	}
	kvs := fdblayer.GetRange(tr, fdb.KeyRange{Begin: rangeBegin, End: rangeEnd}, rangeOpts).GetSliceOrPanic()
	pageLen := len(kvs)
	pkIndexStart := 3 + 1
	cursorStart := 3 + 1
	if opts.Limit > 0 && pageLen > opts.Limit {
		nextTpl, err := dir.Unpack(kvs[opts.Limit].Key)
		if err != nil {
			return nil, err
		}
		if len(nextTpl) > cursorStart {
			result.HasMore = true
			result.NextKey = nextTpl[cursorStart:]
			result.NextPageToken = result.NextKey.Pack()
		}
		kvs = kvs[:opts.Limit]
	}
	futures := make([]fdb.FutureByteSlice, len(kvs))
	for i, kv := range kvs {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		_ = pkIndexStart
		valTpl, err := tuple.Unpack(fdb.Key(kv.Value))
		if err != nil || len(valTpl) < 1 {
			continue
		}
		pkTuple := valTpl[:1]
		keyTpl := make(tuple.Tuple, 2+len(pkTuple))
		keyTpl[0] = CustomerTypeID
		keyTpl[1] = fdblayer.DataNamespace
		copy(keyTpl[2:], pkTuple)
		futures[i] = tr.Get(dir.Pack(keyTpl))
	}
	for _, future := range futures {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		if future == nil {
			continue
		}
		value := future.MustGet()
		if value == nil {
			continue
		}
		entity := &Customer{}
		if err := proto.Unmarshal(value, entity); err != nil {
			return nil, err
		}
		result.Items = append(result.Items, entity)
	}
	return result, nil
}

// GetUniqueByEmail retrieves a single Customer entity by its unique Email index.
func (r *customerRepository) GetUniqueByEmail(ctx context.Context, tx fdblayer.ReadTx, Email string) (*Customer, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	tr := tx.ReadTransaction()
	dir := tx.Dir()

	idxKey := dir.Pack(tuple.Tuple{CustomerTypeID, fdblayer.IndexNamespace, 1, Email})
	idxVal := tr.Get(idxKey).MustGet()
	if idxVal == nil {
		return nil, fmt.Errorf("customer %w", fdblayer.ErrNotFound)
	}
	pkTpl, err := tuple.Unpack(fdb.Key(idxVal))
	if err != nil || len(pkTpl) < 1 {
		return nil, fmt.Errorf("failed to unpack unique index primary key: %w", err)
	}
	pkTuple := pkTpl[:1]
	keyTpl := make(tuple.Tuple, 2+len(pkTuple))
	keyTpl[0] = CustomerTypeID
	keyTpl[1] = fdblayer.DataNamespace
	copy(keyTpl[2:], pkTuple)
	valueFuture := tr.Get(dir.Pack(keyTpl))
	value := valueFuture.MustGet()
	if value == nil {
		return nil, fmt.Errorf("customer %w", fdblayer.ErrNotFound)
	}
	entity := &Customer{}
	if err := proto.Unmarshal(value, entity); err != nil {
		return nil, err
	}
	return entity, nil
}

